// Checks that `kubectl_binary` wires generated files, environment and extra
// arguments through to kubectl, from any working directory.
package tests

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/bazelbuild/rules_go/go/runfiles"
)

// binaries holds the `kubectl_binary` targets under test, resolved through
// runfiles from the rlocationpaths in the test environment.
type binaries struct {
	configmapDryRun string
	configView      string
	manifestKubectl string
	// env is passed to every binary: the test's environment with runfiles
	// variables for the launcher, a scratch HOME and no kubeconfig, so the
	// tests are independent of anything on the host.
	env []string
	// elsewhere is a directory with nothing in it, used as the working
	// directory to show that generated files are found through runfiles.
	elsewhere string
}

func setup(t *testing.T) *binaries {
	t.Helper()

	r, err := runfiles.New()
	if err != nil {
		t.Fatalf("failed to locate runfiles: %v", err)
	}
	locate := func(variable string) string {
		path, err := r.Rlocation(os.Getenv(variable))
		if err != nil {
			t.Fatalf("failed to locate %s: %v", variable, err)
		}
		return path
	}

	tmp := t.TempDir()
	home := filepath.Join(tmp, "home")
	elsewhere := filepath.Join(tmp, "elsewhere")
	for _, dir := range []string{home, elsewhere} {
		if err := os.Mkdir(dir, 0o755); err != nil {
			t.Fatal(err)
		}
	}

	env := append(os.Environ(), r.Env()...)
	env = append(env, "HOME="+home, "KUBECONFIG=", "BUILD_WORKING_DIRECTORY=")

	return &binaries{
		configmapDryRun: locate("CONFIGMAP_DRY_RUN"),
		configView:      locate("CONFIG_VIEW"),
		manifestKubectl: locate("MANIFEST_KUBECTL"),
		env:             env,
		elsewhere:       elsewhere,
	}
}

// run executes a binary from `elsewhere` and returns its combined output.
func (b *binaries) run(t *testing.T, binary string, extraEnv []string, args ...string) (string, error) {
	t.Helper()
	cmd := exec.Command(binary, args...)
	cmd.Dir = b.elsewhere
	cmd.Env = append(append([]string{}, b.env...), extraEnv...)
	output, err := cmd.CombinedOutput()
	return strings.TrimSpace(string(output)), err
}

func (b *binaries) mustRun(t *testing.T, binary string, extraEnv []string, args ...string) string {
	t.Helper()
	output, err := b.run(t, binary, extraEnv, args...)
	if err != nil {
		t.Fatalf("%s %s failed: %v\n%s", filepath.Base(binary), strings.Join(args, " "), err, output)
	}
	return output
}

func TestKubectlBinary(t *testing.T) {
	b := setup(t)

	t.Run("a generated file referenced with $(rlocationpath) is found from another directory", func(t *testing.T) {
		output := b.mustRun(t, b.configmapDryRun, []string{"BUILD_WORKING_DIRECTORY=" + b.elsewhere})
		for _, want := range []string{"name: binary-test", "generated by bazel"} {
			if !strings.Contains(output, want) {
				t.Errorf("expected %q in the output, got:\n%s", want, output)
			}
		}
	})

	t.Run("arguments on the command line are appended", func(t *testing.T) {
		output := b.mustRun(t, b.configmapDryRun, nil, "--namespace=appended")
		if !strings.Contains(output, "namespace: appended") {
			t.Errorf("expected the namespace from the command line, got:\n%s", output)
		}
	})

	t.Run("env is set for kubectl", func(t *testing.T) {
		output := b.mustRun(t, b.configView, nil)
		if want := "https://binary-test.invalid:6443"; output != want {
			t.Errorf("expected the server from the generated kubeconfig %q, got: %q", want, output)
		}
	})

	t.Run("kubectl takes a configured flag ahead of a verb given on the command line", func(t *testing.T) {
		// `--local` keeps kubectl off the network, which the sandbox has none of.
		output := b.mustRun(t, b.manifestKubectl, nil, "label", "--local", "--dry-run=client", "--output=name", "checked=yes")
		if want := "configmap/manifest-test"; output != want {
			t.Errorf("expected the manifest to be labelled as %q, got: %q", want, output)
		}
	})

	t.Run("a verb that takes no file rejects the flag", func(t *testing.T) {
		output, err := b.run(t, b.manifestKubectl, nil, "version", "--client")
		if err == nil {
			t.Fatalf("expected kubectl to reject --filename for 'version', got:\n%s", output)
		}
		if !strings.Contains(output, "unknown flag: --filename") {
			t.Errorf("expected an unknown flag error, got:\n%s", output)
		}
	})
}
